args.command:
curl -s -m 20 "https://www.36kr.com/search/articles/%E4%BA%BA%E5%B7%A5%E6%99%BA%E8%83%BD%E6%94%BF%E7%AD%96" -H "User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36" -o /tmp/kr.html; wc -c /tmp/kr.html; python3 -c "
import re, html
content = open('/tmp/kr.html', encoding='utf-8', errors='ignore').read()
titles = re.findall(r'<span class=\"article-item-title[^\"]*\"[^>]*>(.*?)</span>', content, re.S)
if not titles:
    titles = re.findall(r'\"title\":\"(.*?)\"', content)
for t in titles[:15]:
    t = html.unescape(t).strip()
    if t: print('-', t[:100])
"
